  [IpcChannel.PluginsEnable]: "cloud:operate",
  [IpcChannel.PluginsDisable]: "cloud:operate",
  [IpcChannel.PluginsReload]: "cloud:operate",
  [IpcChannel.PluginsUpdate]: "cloud:operate",
  [IpcChannel.PluginsRemove]: "cloud:operate",
