  [IpcChannel.BackupRestore]: "cloud:operate",
  [IpcChannel.BackupDelete]: "cloud:operate",
  [IpcChannel.RecoveryRun]: "cloud:operate",
  [IpcChannel.SupportGenerateBundle]: "cloud:operate",
